#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage:\n  %s [OPTION...] [FILE...]\n\n  Chafa (Character Art Facsimile) terminal graphics and character art generator.\n", argv[0]);
        fprintf(stderr, "\nGeneral options:\n");
        fprintf(stderr, "      --files=PATH   Read list of files to process from PATH, or \"-\" for stdin.\n");
        fprintf(stderr, "      --files0=PATH  Similar to --files, using NUL separator instead of newline.\n");
        fprintf(stderr, "  -h, --help         Show help.\n");
        fprintf(stderr, "      --probe=ARG    Probe terminal's capabilities and wait for response [auto,\n");
        fprintf(stderr, "                     on, off]. A positive real number denotes the maximum time\n");
        fprintf(stderr, "                     to wait for a response, in seconds. Defaults to 5.0.\n");
        fprintf(stderr, "      --probe-mode=ARG  How to probe the terminal [any, ctty, stdio].\n");
        fprintf(stderr, "      --version      Show version.\n");
        fprintf(stderr, "  -v, --verbose      Be verbose.\n");
        fprintf(stderr, "\nIf your OS comes with manual pages, you can type 'man chafa' for more.\n");
        return 1;
    }

    // Check for help flag
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            printf("Usage:\n  %s [OPTION...] [FILE...]\n\n  Chafa (Character Art Facsimile) terminal graphics and character art generator.\n", argv[0]);
            printf("\nGeneral options:\n");
            printf("      --files=PATH   Read list of files to process from PATH, or \"-\" for stdin.\n");
            printf("      --files0=PATH  Similar to --files, using NUL separator instead of newline.\n");
            printf("  -h, --help         Show help.\n");
            printf("      --probe=ARG    Probe terminal's capabilities and wait for response [auto,\n");
            printf("                     on, off]. A positive real number denotes the maximum time\n");
            printf("                     to wait for a response, in seconds. Defaults to 5.0.\n");
            printf("      --probe-mode=ARG  How to probe the terminal [any, ctty, stdio].\n");
            printf("      --version      Show version.\n");
            printf("  -v, --verbose      Be verbose.\n");
            printf("\nOutput encoding:\n");
            printf("  -f, --format=FORMAT  Set output format; one of [iterm, kitty, sixels,\n");
            printf("                     symbols]. Iterm, kitty and sixels yield much higher\n");
            printf("                     quality but enjoy limited support. Symbols mode yields\n");
            printf("                     beautiful character art.\n");
            printf("  -O, --optimize=NUM  Compress the output by using control sequences\n");
            printf("                     intelligently [0-9]. 0 disables, 9 enables every\n");
            printf("                     available optimization. Defaults to 5, except for when\n");
            printf("                     used with \"-c none\", where it defaults to 0.\n");
            printf("      --relative=BOOL  Use relative cursor positioning [on, off]. When on,\n");
            printf("                     control sequences will be used to position images relative\n");
            printf("                     to the cursor. When off, newlines will be used to separate\n");
            printf("                     rows instead for e.g. 'less -R' interop. Defaults to off.\n");
            printf("      --passthrough=MODE  Graphics protocol passthrough [auto, none, screen,\n");
            printf("                     tmux]. Used to show pixel graphics through multiplexers.\n");
            printf("      --polite=BOOL  Polite mode [on, off]. Inhibits escape sequences that may\n");
            printf("                     confuse other programs. Defaults to off.\n");
            printf("\nSize and layout:\n");
            printf("      --align=ALIGN  Horizontal and vertical alignment (e.g. \"top,left\").\n");
            printf("      --clear        Clear screen before processing each file.\n");
            printf("      --exact-size=MODE  Try to match the input's size exactly [auto, on, off].\n");
            printf("      --fit-width    Fit images to view's width, possibly exceeding its height.\n");
            printf("      --font-ratio=W/H  Target font's width/height ratio. Can be specified as\n");
            printf("                     a real number or a fraction. Defaults to 1/2.\n");
            printf("      --grid=CxR     Lay out images in a grid of CxR columns/rows per screenful.\n");
            printf("                     C or R may be omitted, e.g. \"--grid 4\". Can be \"auto\".\n");
            printf("  -g                 Alias for \"--grid auto\".\n");
            printf("      --label=BOOL   Labeling [on, off]. Filenames below images. Default off.\n");
            printf("  -l                 Alias for \"--label on\".\n");
            printf("      --link=BOOL    Link labels [auto, on, off]. Turns labels into clickable\n");
            printf("                     hyperlinks. Use with \"--label on\". Defaults to auto.\n");
            printf("      --margin-bottom=NUM  When terminal size is detected, reserve at least NUM\n");
            printf("                     rows at the bottom as a safety margin. Can be used to\n");
            printf("                     prevent images from scrolling out. Defaults to 1.\n");
            printf("      --margin-right=NUM  When terminal size is detected, reserve at least NUM\n");
            printf("                     columns safety margin on right-hand side. Defaults to 0.\n");
            printf("      --scale=NUM    Scale image, respecting view's dimensions. 1.0 approximates\n");
            printf("                     image's pixel dimensions. Specify \"max\" to fit view.\n");
            printf("                     Defaults to 1.0 for pixel graphics and 4.0 for symbols.\n");
            printf("  -s, --size=WxH     Set maximum image dimensions in columns and rows. By\n");
            printf("                     default this will be equal to the view size.\n");
            printf("      --stretch      Stretch image to fit output dimensions; ignore aspect.\n");
            printf("                     Implies --scale max.\n");
            printf("      --view-size=WxH  Set the view size in columns and rows. By default this\n");
            printf("                     will be the size of your terminal, or 80x25 if size\n");
            printf("                     detection fails. If one dimension is omitted, it will\n");
            printf("                     be set to a reasonable approximation of infinity.\n");
            printf("\nAnimation and timing:\n");
            printf("      --animate=BOOL  Whether to allow animation [on, off]. Defaults to on.\n");
            printf("                     When off, will show a still frame from each animation.\n");
            printf("  -d, --duration=SECONDS  How long to show each file. If showing a single file,\n");
            printf("                     defaults to zero for a still image and infinite for an\n");
            printf("                     animation. For multiple files, defaults to zero. Animations\n");
            printf("                     will always be played through at least once.\n");
            printf("      --speed=SPEED  Animation speed. Either a unitless multiplier, or a real\n");
            printf("                     number followed by \"fps\" to apply a specific framerate.\n");
            printf("      --watch        Watch a single input file, redisplaying it whenever its\n");
            printf("                     contents change. Will run until manually interrupted\n");
            printf("                     or, if --duration is set, until it expires.\n");
            printf("\nColors and processing:\n");
            printf("      --bg=COLOR     Background color of display (color name or hex).\n");
            printf("  -c, --colors=MODE  Set output color mode; one of [none, 2, 8, 16/8, 16, 240,\n");
            printf("                     256, full]. Defaults to best guess.\n");
            printf("      --color-extractor=EXTR  Method for extracting color from an area\n");
            printf("                     [average, median]. Average is the default.\n");
            printf("      --color-space=CS  Color space used for quantization; one of [rgb, din99d].\n");
            printf("                     Defaults to rgb, which is faster but less accurate.\n");
            printf("      --dither=DITHER  Set output dither mode; one of [none, ordered,\n");
            printf("                     diffusion, noise]. No effect with 24-bit color. Defaults to\n");
            printf("                     noise for sixels, none otherwise.\n");
            printf("      --dither-grain=WxH  Set dimensions of dither grains in 1/8ths of a\n");
            printf("                     character cell [1, 2, 4, 8]. Defaults to 4x4.\n");
            printf("      --dither-intensity=NUM  Multiplier for dither intensity [0.0 - inf].\n");
            printf("                     Defaults to 1.0.\n");
            printf("      --fg=COLOR     Foreground color of display (color name or hex).\n");
            printf("      --invert       Swaps --fg and --bg. Useful with light terminal background.\n");
            printf("  -p, --preprocess=BOOL  Image preprocessing [on, off]. Defaults to on with 16\n");
            printf("                     colors or lower, off otherwise.\n");
            printf("  -t, --threshold=NUM  Lower threshold for full transparency [0.0 - 1.0].\n");
            printf("\nResource allocation:\n");
            printf("      --threads=NUM  Maximum number of CPU threads to use. If left unspecified\n");
            printf("                     or negative, this will equal available CPU cores.\n");
            printf("  -w, --work=NUM     How hard to work in terms of CPU and memory [1-9]. 1 is the\n");
            printf("                     cheapest, 9 is the most accurate. Defaults to 5.\n");
            printf("\nExtra options for symbol encoding:\n");
            printf("      --fg-only      Leave the background color untouched. This produces\n");
            printf("                     character-cell output using foreground colors only.\n");
            printf("      --fill=SYMS    Specify character symbols to use for fill/gradients.\n");
            printf("                     Defaults to none. See below for full usage.\n");
            printf("      --glyph-file=FILE  Load glyph information from FILE, which can be any\n");
            printf("                     font file supported by FreeType (TTF, PCF, etc).\n");
            printf("      --symbols=SYMS  Specify character symbols to employ in final output.\n");
            printf("                     See below for full usage and a list of symbol classes.\n");
            printf("\nAccepted classes for --symbols and --fill:\n");
            printf("  all        ascii   braille   extra      imported  narrow   solid      ugly\n");
            printf("  alnum      bad     diagonal  geometric  inverted  none     space      vhalf\n");
            printf("  alpha      block   digit     half       latin     quad     stipple    wedge\n");
            printf("  ambiguous  border  dot       hhalf      legacy    sextant  technical  wide\n");
            printf("\n  These can be combined with + and -, e.g. block+border-diagonal or all-wide.\n");
            printf("\nExamples:\n");
            printf("  $ chafa --scale max in.jpg                           # As big as will fit\n");
            printf("  $ chafa --clear --align mid,mid -d 5 *.gif           # Centered slideshow\n");
            printf("  $ chafa -f symbols --symbols ascii -c none in.png    # Old-school ASCII art\n");
            printf("  $ find /usr -type f -print0 | chafa --files0 - -g -l # System images (Unix)\n");
            printf("\nIf your OS comes with manual pages, you can type 'man chafa' for more.\n");
            return 0;
        }
        if (strcmp(argv[i], "--version") == 0) {
            printf("Chafa version 1.19.0\n\n");
            printf("Loaders:  GIF JPEG PNG QOI SVG TIFF WebP XWD\n");
            printf("Features: mmx sse4.1 popcnt avx2\n");
            printf("Applying: mmx sse4.1 popcnt avx2\n\n");
            printf("Copyright (C) 2018-2025 Hans Petter Jansson et al.\n");
            printf("Incl. libnsgif copyright (C) 2004 Richard Wilson, copyright (C) 2008 Sean Fox\n");
            printf("Incl. LodePNG copyright (C) 2005-2018 Lode Vandevenne\n");
            printf("Incl. QOI decoder copyright (C) 2021 Dominic Szablewski\n\n");
            printf("This is free software; see the source for copying conditions. There is NO\n");
            printf("warranty; not even for MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.\n\n");
            return 0;
        }
    }

    // Process files
    for (int i = 1; i < argc; i++) {
        if (argv[i][0] == '-') continue; // Skip options

        struct stat st;
        if (stat(argv[i], &st) != 0) {
            fprintf(stderr, "%s: Failed to open '%s': No such file or directory\n", argv[0], argv[i]);
            return 2;
        }
    }

    return 0;
}
