    char *format;
    char *size;
    char *colors;
    char *symbols;
    int verbose;
} ChafaConfig;

// Initialize configuration with defaults
ChafaConfig* config_new(void) {
    ChafaConfig *cfg = malloc(sizeof(ChafaConfig));
    cfg->format = "symbols";
    cfg->size = NULL;
    cfg->colors = NULL;
    cfg->symbols = NULL;
    cfg->verbose = 0;
    return cfg;
}

void config_free(ChafaConfig *cfg) {
    if (cfg) {
        if (cfg->format && strcmp(cfg->format, "symbols") != 0) free(cfg->format);
        if (cfg->size) free(cfg->size);
        if (cfg->colors) free(cfg->colors);
        if (cfg->symbols) free(cfg->symbols);
        free(cfg);
    }
}

// Simple image structure
typedef struct {
    int width;
    int height;
    unsigned char* data;  // For now, just raw bytes
} Image;

// Minimal image loading - just read file and try to detect format
Image* load_image(const char *filename) {
    FILE *f = fopen(filename, "rb");
    if (!f) {
        return NULL;
    }

    Image *img = malloc(sizeof(Image));
    img->width = 1;
    img->height = 1;

    // Read file and store raw data for now
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    img->data = malloc(size);
    if (fread(img->data, 1, size, f) < size) {
        // Error
    }
    fclose(f);

    return img;
}

