        if (strncmp(arg, "-f", 2) == 0 || strncmp(arg, "--format", 8) == 0) {
            if (strncmp(arg, "-f", 2) == 0 && strlen(arg) > 2) {
                cfg->format = arg + 2;
            } else if (strncmp(arg, "--format=", 9) == 0) {
                cfg->format = arg + 9;
            } else if (i + 1 < argc) {
                cfg->format = argv[++i];
            }
            continue;
        }

        if (strncmp(arg, "-s", 2) == 0 || strncmp(arg, "--size", 6) == 0) {
            if (strncmp(arg, "-s", 2) == 0 && strlen(arg) > 2) {
                cfg->size = arg + 2;
            } else if (strncmp(arg, "--size=", 7) == 0) {
                cfg->size = arg + 7;
