                cfg->colors = arg + 2;
            } else if (strncmp(arg, "--colors=", 9) == 0) {
                cfg->colors = arg + 9;
            } else if (i + 1 < argc) {
                cfg->colors = argv[++i];
            }
            continue;
        }

        // Skip other options
        if (arg[0] == '-') {
            // Parse option parameters
            if (strchr(arg, '=') != NULL) {
                // Option with value
                continue;
            }
            // Check if next arg is a value for this option
            if (i + 1 < argc && argv[i+1][0] != '-') {
                i++;
            }
            continue;
        }

        // It's a file
        if (file_count < 256) {
            files[file_count++] = arg;
        }
    }

    // Process files
    if (file_count == 0) {
        fprintf(stderr, "Usage:\n  %s [OPTION...] [FILE...]\n\n  Chafa (Character Art Facsimile) terminal graphics and character art generator.\n", argv[0]);
        config_free(cfg);
        return 1;
    }

    for (int i = 0; i < file_count; i++) {
        struct stat st;
        if (stat(files[i], &st) != 0) {
            fprintf(stderr, "%s: Failed to open '%s': No such file or directory\n", argv[0], files[i]);
            config_free(cfg);
            return 2;
        }

        Image *img = load_image(files[i]);
        if (!img) {
            fprintf(stderr, "%s: Failed to open '%s': No such file or directory\n", argv[0], files[i]);
            config_free(cfg);
            return 2;
        }

        generate_output(cfg, img);
        image_free(img);
    }

    config_free(cfg);
    return 0;
}
