// Simple PPM reader for testing
RawImage* read_ppm(const char* filename) {
    FILE* f = fopen(filename, "rb");
    if (!f) return NULL;

    RawImage* img = calloc(1, sizeof(RawImage));

    // Read magic
    char magic[3];
    if (fscanf(f, "%2s", magic) != 1) {
        free(img);
        fclose(f);
        return NULL;
    }

    // Minimal PPM support
    if (strcmp(magic, "P6") != 0) {
        free(img);
        fclose(f);
        return NULL;
    }

    int max_val;
    if (fscanf(f, "%d %d %d", &img->width, &img->height, &max_val) != 3) {
        free(img);
        fclose(f);
        return NULL;
    }

    fgetc(f); // consume whitespace

    size_t pixel_count = img->width * img->height;
    img->data = malloc(pixel_count * 4);
    img->data_size = pixel_count * 4;

    for (size_t i = 0; i < pixel_count; i++) {
        uint8_t r, g, b;
        if (fread(&r, 1, 1, f) != 1 || 
            fread(&g, 1, 1, f) != 1 ||
            fread(&b, 1, 1, f) != 1) {
            break;
        }
        img->data[i*4 + 0] = r;
        img->data[i*4 + 1] = g;
        img->data[i*4 + 2] = b;
        img->data[i*4 + 3] = 255;
    }

    fclose(f);
    return img;
}

// Very simple image loading - just read as bytes and hope for best
RawImage* load_image_simple(const char* filename) {
    FILE* f = fopen(filename, "rb");
    if (!f) return NULL;

    // For now, return a 1x1 placeholder image
    RawImage* img = calloc(1, sizeof(RawImage));
    img->width = 1;
    img->height = 1;
    img->data = calloc(4, sizeof(uint8_t));
    img->data_size = 4;
    // Black pixel with full alpha
    img->data[0] = 0;
    img->data[1] = 0;
    img->data[2] = 0;
    img->data[3] = 255;

    fclose(f);
    return img;
}

