void generate_simple_output(ChafaConfig* cfg, RawImage* img) {
    // Generate simple character art output
    const char* chars_full = "@%#*+=-:. ";
    const char* chars_ascii = "Mo.  ";

    const char* chars = chars_full;
    int char_count = strlen(chars);

    if (cfg->colors && strcmp(cfg->colors, "none") == 0) {
        chars = chars_ascii;
        char_count = strlen(chars);
    }

    int out_width = cfg->width;
    int out_height = cfg->height;

    if (cfg->size) {
        sscanf(cfg->size, "%dx%d", &out_width, &out_height);
    }

    // Very simple dithering based on image data
    if (img->data_size < 4) {
        printf("%c\n", chars[0]);
        return;
    }

    uint8_t r = img->data[0];
    uint8_t g = img->data[1];
    uint8_t b = img->data[2];

    // Convert to luminance
    int luminance = (r * 299 + g * 587 + b * 114) / 1000;
    int char_idx = (luminance * char_count) / 256;
    if (char_idx >= char_count) char_idx = char_count - 1;

    printf("%c\n", chars[char_idx]);
}

int main(int argc, char **argv) {
    ChafaConfig *cfg = config_new();
    int file_count = 0;
    char **files = malloc(sizeof(char*) * 256);

    // Parse arguments
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];

        if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0) {
            print_help(argv[0]);
            free(files);
            free(cfg);
            return 0;
        }

        if (strcmp(arg, "--version") == 0) {
            print_version();
            free(files);
            free(cfg);
            return 0;
        }

        if (strcmp(arg, "-v") == 0 || strcmp(arg, "--verbose") == 0) {
            cfg->verbose = 1;
            continue;
        }

        // Parse options with = syntax
        if (strstr(arg, "=")) {
            char* eq = strchr(arg, '=');
            char* value = eq + 1;

            if (strncmp(arg, "-f", 2) == 0 || strncmp(arg, "--format", 8) == 0) {
                cfg->format = value;
            } else if (strncmp(arg, "-s", 2) == 0 || strncmp(arg, "--size", 6) == 0) {
                cfg->size = value;
            } else if (strncmp(arg, "-c", 2) == 0 || strncmp(arg, "--colors", 8) == 0) {
                cfg->colors = value;
            } else if (strncmp(arg, "--bg", 4) == 0) {
                cfg->bg = value;
            } else if (strncmp(arg, "--fg", 4) == 0) {
                cfg->fg = value;
            }
            continue;
        }

        // Skip other options
        if (arg[0] == '-') {
            // Check if next arg is a value
            if (i + 1 < argc && argv[i+1][0] != '-') {
                i++;
            }
            continue;
        }

        // It's a file
        files[file_count++] = arg;
    }

    if (file_count == 0) {
        fprintf(stderr, "Usage:\n  %s [OPTION...] [FILE...]\n\n  Chafa (Character Art Facsimile) terminal graphics and character art generator.\n", argv[0]);
        free(files);
        free(cfg);
        return 1;
    }

    for (int i = 0; i < file_count; i++) {
        struct stat st;
        if (stat(files[i], &st) != 0) {
            fprintf(stderr, "%s: Failed to open '%s': No such file or directory\n", argv[0], files[i]);
            free(files);
            free(cfg);
            return 2;
        }

        RawImage *img = load_image_simple(files[i]);
        if (!img) {
            fprintf(stderr, "%s: Failed to open '%s': No such file or directory\n", argv[0], files[i]);
            free(files);
            free(cfg);
            return 2;
        }

        generate_simple_output(cfg, img);
        free_image(img);
    }

    free(files);
    free(cfg);
    return 0;
}
