#ifndef IMAGE_LOADERS_H
#define IMAGE_LOADERS_H

#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int width;
    int height;
    uint8_t* pixels;  // RGBA format
} SimpleImage;

// Detect image format from file signature
int detect_format(const char* filename) {
    FILE* f = fopen(filename, "rb");
    if (!f) return -1;

    uint8_t magic[16];
    size_t n = fread(magic, 1, 16, f);
    fclose(f);

    // PNG: 89 50 4E 47
    if (n >= 4 && magic[0] == 0x89 && magic[1] == 0x50 && 
        magic[2] == 0x4E && magic[3] == 0x47) {
        return 1; // PNG
    }

    // JPEG: FF D8 FF
    if (n >= 3 && magic[0] == 0xFF && magic[1] == 0xD8 && magic[2] == 0xFF) {
        return 2; // JPEG
