            sys.exit(0)
        elif arg.startswith("-s") or arg.startswith("--size"):
            if "=" in arg:
                size_str = arg.split("=")[1]
                parts = size_str.split("x")
                if len(parts) == 2:
                    width = int(parts[0])
                    height = int(parts[1])
            elif i + 1 < len(sys.argv):
                size_str = sys.argv[i + 1]
                parts = size_str.split("x")
                if len(parts) == 2:
                    width = int(parts[0])
                    height = int(parts[1])
                i += 1
        elif arg.startswith("-c") or arg.startswith("--colors"):
            if "=" in arg:
                colors = arg.split("=")[1]
            elif i + 1 < len(sys.argv):
                colors = sys.argv[i + 1]
                i += 1
        elif arg.startswith("-f") or arg.startswith("--format"):
            if "=" in arg:
                fmt = arg.split("=")[1]
            elif i + 1 < len(sys.argv):
                fmt = sys.argv[i + 1]
                i += 1
        elif not arg.startswith("-"):
            files.append(arg)

        i += 1

    if not files:
        print(f"Usage: chafa [OPTION...] [FILE...]", file=sys.stderr)
        sys.exit(1)

    for filename in files:
        if not os.path.exists(filename):
            print(f"chafa: Failed to open '{filename}': No such file or directory", file=sys.stderr)
            sys.exit(2)

        img = load_image(filename)
        output = image_to_ascii(img, width, height)
        print(output)

if __name__ == "__main__":
    main()
