#!/usr/bin/env python3

import sys
import os
import struct
import zlib
import math
from io import BytesIO

class PNG:
    def __init__(self, data):
        self.data = BytesIO(data)
        self.width = 0
        self.height = 0
        self.depth = 8
        self.color_type = 0
        self.pixels = None
        self.parse()

    def read_chunk(self):
        length_data = self.data.read(4)
        if len(length_data) < 4:
            return None
        length = struct.unpack('>I', length_data)[0]
        chunk_type = self.data.read(4)
        chunk_data = self.data.read(length)
        crc = self.data.read(4)
        return chunk_type, chunk_data

    def parse(self):
        # Read PNG signature
        sig = self.data.read(8)
        if sig != b'\x89PNG\r\n\x1a\n':
            return

        # Read chunks
        while True:
            chunk = self.read_chunk()
            if not chunk:
                break

            chunk_type, chunk_data = chunk

            if chunk_type == b'IHDR':
                self.width, self.height, self.depth, self.color_type = struct.unpack('>IIBBB', chunk_data[:13])
            elif chunk_type == b'IDAT':
                if not hasattr(self, 'idat_data'):
                    self.idat_data = b''
                self.idat_data += chunk_data
            elif chunk_type == b'IEND':
                break

        # Decompress image data
        if hasattr(self, 'idat_data'):
            try:
                raw_data = zlib.decompress(self.idat_data)
                self.pixels = self.decode_pixels(raw_data)
            except:
                pass

    def decode_pixels(self, data):
        # Simple RGB extraction
        pixels = []
        if self.color_type == 0:  # Grayscale
            bytespp = 1
        elif self.color_type == 2:  # RGB
            bytespp = 3
        elif self.color_type == 3:  # Indexed
            bytespp = 1
        elif self.color_type == 4:  # Grayscale + Alpha
            bytespp = 2
        elif self.color_type == 6:  # RGBA
            bytespp = 4
        else:
            bytespp = 1

        scanline_bytes = self.width * bytespp + 1

        for y in range(self.height):
            offset = y * scanline_bytes
            if offset + scanline_bytes > len(data):
                break

            filter_type = data[offset]
            scanline = bytearray(data[offset+1:offset+scanline_bytes])

            # Apply filter (naive implementation)
            for x in range(self.width):
                if bytespp >= 3:
                    idx = x * bytespp
                    if idx + 2 < len(scanline):
                        r = scanline[idx]
                        g = scanline[idx+1]
                        b = scanline[idx+2]
                        a = scanline[idx+3] if bytespp == 4 else 255
                        pixels.append((r, g, b, a))

        return pixels[:self.width * self.height]

def load_image(filename):
    try:
        with open(filename, 'rb') as f:
            data = f.read()

        # Check format
        if data[:4] == b'\x89PNG':
            png = PNG(data)
            return png
    except:
        pass

    return None

def get_luminance(r, g, b):
    return int(0.299 * r + 0.587 * g + 0.114 * b)

def image_to_ascii(png, width, height):
    chars = "@%#*+=-:. "

    if not png or not png.pixels or len(png.pixels) == 0:
        return "@"

    # Get average luminance
    total_lum = 0
    for r, g, b, a in png.pixels:
        total_lum += get_luminance(r, g, b)

    avg_lum = total_lum // len(png.pixels) if png.pixels else 128

    # Map to character
    idx = int((avg_lum / 256.0) * len(chars))
    if idx >= len(chars):
        idx = len(chars) - 1

    return chars[idx]

def main():
    if len(sys.argv) < 2:
        print("Usage: chafa [OPTIONS] [FILE...]")
