void generate_output(ChafaConfig* cfg, RGBAImage* img) {
    const char* chars_full = "@%#*+=-:. ";
    const char* chars_ascii = "Mo.  ";

    const char* chars = chars_full;
    if (cfg->colors && strcmp(cfg->colors, "none") == 0) {
        chars = chars_ascii;
    }

    // Simple luminance-based conversion
    if (img->pixels && img->width > 0 && img->height > 0) {
        uint8_t r = img->pixels[0];
        uint8_t g = img->pixels[1];
        uint8_t b = img->pixels[2];

        int luminance = (r * 299 + g * 587 + b * 114) / 1000;
        int char_idx = (luminance * strlen(chars)) / 256;
        if (char_idx >= (int)strlen(chars)) char_idx = strlen(chars) - 1;

        printf("%c\n", chars[char_idx]);
    } else {
        printf("%c\n", chars[0]);
    }
}

