typedef struct {
    char* format;
    char* size;
    char* colors;
    char* symbols;
    char* bg;
    char* fg;
    int width;
    int height;
    int verbose;
} ChafaConfig;

typedef struct {
    int width;
    int height;
    uint8_t* pixels;  // RGBA
} RGBAImage;

ChafaConfig* config_new(void) {
    ChafaConfig *cfg = calloc(1, sizeof(ChafaConfig));
    cfg->format = "symbols";
    cfg->width = 80;
    cfg->height = 25;
    return cfg;
