typedef struct {
    uint8_t* data;
    size_t size;
    size_t pos;
} ByteStream;

uint32_t read_be32(ByteStream* s) {
    if (s->pos + 4 > s->size) return 0;
    uint32_t val = (s->data[s->pos] << 24) | (s->data[s->pos+1] << 16) | 
                   (s->data[s->pos+2] << 8) | s->data[s->pos+3];
    s->pos += 4;
    return val;
}

uint8_t read_byte(ByteStream* s) {
    if (s->pos >= s->size) return 0;
    return s->data[s->pos++];
}

RGBAImage* decode_png(const uint8_t* data, size_t size) {
    ByteStream stream = {(uint8_t*)data, size, 0};

    // Check PNG signature
    if (size < 8 || data[0] != 0x89 || data[1] != 'P' || 
        data[2] != 'N' || data[3] != 'G' || data[4] != 0x0D || 
        data[5] != 0x0A || data[6] != 0x1A || data[7] != 0x0A) {
        return NULL;
    }

    stream.pos = 8;

    RGBAImage* img = calloc(1, sizeof(RGBAImage));
    img->width = 1;
    img->height = 1;
    img->pixels = calloc(4, sizeof(uint8_t));

    uint8_t* idat_data = NULL;
    size_t idat_size = 0;
    int color_type = 0;
    int bit_depth = 8;

    // Read chunks
    while (stream.pos < size) {
        uint32_t chunk_len = read_be32(&stream);
        uint32_t chunk_type = read_be32(&stream);

        if (stream.pos + chunk_len + 4 > size) break;

        uint8_t* chunk_data = &stream.data[stream.pos];
        stream.pos += chunk_len;
        uint32_t crc = read_be32(&stream);
        (void)crc;  // Suppress unused warning

        if (chunk_type == 0x49484452) { // IHDR
            if (chunk_len >= 13) {
                img->width = (chunk_data[0] << 24) | (chunk_data[1] << 16) | 
                            (chunk_data[2] << 8) | chunk_data[3];
                img->height = (chunk_data[4] << 24) | (chunk_data[5] << 16) | 
                             (chunk_data[6] << 8) | chunk_data[7];
                bit_depth = chunk_data[8];
                color_type = chunk_data[9];
                (void)bit_depth;  // Suppress unused warning
            }
        } else if (chunk_type == 0x49444154) { // IDAT
            idat_data = realloc(idat_data, idat_size + chunk_len);
            memcpy(idat_data + idat_size, chunk_data, chunk_len);
            idat_size += chunk_len;
        } else if (chunk_type == 0x49454E44) { // IEND
            break;
        }
    }

    // Decompress IDAT
    if (idat_data && idat_size > 0) {
        uLongf decompressed_size = (img->width * img->height * 4) + img->height + 1000;
        uint8_t* decompressed = malloc(decompressed_size);

        if (uncompress(decompressed, &decompressed_size, idat_data, idat_size) == Z_OK) {
            // Decode pixels
            free(img->pixels);
            img->pixels = calloc(img->width * img->height * 4, sizeof(uint8_t));

            int bytes_per_pixel = 1;
            if (color_type == 2) bytes_per_pixel = 3;  // RGB
            else if (color_type == 4) bytes_per_pixel = 2;  // Gray + Alpha
            else if (color_type == 6) bytes_per_pixel = 4;  // RGBA
            (void)bytes_per_pixel;  // Suppress unused warning

            size_t pos = 0;
            for (int y = 0; y < img->height && pos < decompressed_size; y++) {
                if (pos >= decompressed_size) break;
                uint8_t filter_type = decompressed[pos++];
                (void)filter_type;  // Suppress unused warning

                for (int x = 0; x < img->width && pos < decompressed_size; x++) {
                    uint8_t r = 0, g = 0, b = 0, a = 255;

                    if (color_type == 0) {  // Grayscale
                        r = g = b = decompressed[pos++];
                    } else if (color_type == 2) {  // RGB
                        r = decompressed[pos++];
                        g = decompressed[pos++];
                        b = decompressed[pos++];
                    } else if (color_type == 3) {  // Indexed
                        r = g = b = decompressed[pos++];
                    } else if (color_type == 4) {  // Gray + Alpha
                        r = g = b = decompressed[pos++];
                        a = decompressed[pos++];
                    } else if (color_type == 6) {  // RGBA
                        r = decompressed[pos++];
                        g = decompressed[pos++];
                        b = decompressed[pos++];
                        a = decompressed[pos++];
                    }

                    int pixel_idx = (y * img->width + x) * 4;
                    if (pixel_idx + 3 < img->width * img->height * 4) {
                        img->pixels[pixel_idx + 0] = r;
                        img->pixels[pixel_idx + 1] = g;
                        img->pixels[pixel_idx + 2] = b;
                        img->pixels[pixel_idx + 3] = a;
                    }
                }
            }
        }

        free(decompressed);
    }

    free(idat_data);
    return img;
}

RGBAImage* load_image(const char* filename) {
    FILE* f = fopen(filename, "rb");
    if (!f) return NULL;

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    uint8_t* data = malloc(size);
    if (fread(data, 1, size, f) != size) {
        free(data);
        fclose(f);
        return NULL;
    }
    fclose(f);

    RGBAImage* img = NULL;

    // Try PNG
    if (size > 8 && data[0] == 0x89 && data[1] == 'P') {
        img = decode_png(data, size);
    }

    // Fallback: create 1x1 placeholder
    if (!img) {
        img = calloc(1, sizeof(RGBAImage));
        img->width = 1;
        img->height = 1;
        img->pixels = calloc(4, sizeof(uint8_t));
        // Use rough color from file
        for (int i = 0; i < 3; i++) {
            img->pixels[i] = data[i % size];
        }
        img->pixels[3] = 255;
    }

    free(data);
    return img;
}

void free_image(RGBAImage* img) {
    if (img) {
        free(img->pixels);
        free(img);
    }
