// Simple image scaling
RGBAImage* scale_image(RGBAImage* src, int target_w, int target_h) {
    if (!src) return NULL;

    RGBAImage* dst = calloc(1, sizeof(RGBAImage));
    dst->width = target_w;
    dst->height = target_h;
    dst->pixels = calloc(target_w * target_h * 4, sizeof(uint8_t));

    float sx = (float)src->width / target_w;
    float sy = (float)src->height / target_h;

    for (int y = 0; y < target_h; y++) {
        for (int x = 0; x < target_w; x++) {
            int src_x = (int)(x * sx);
            int src_y = (int)(y * sy);

            if (src_x >= src->width) src_x = src->width - 1;
            if (src_y >= src->height) src_y = src->height - 1;
            if (src_x < 0) src_x = 0;
            if (src_y < 0) src_y = 0;

            int src_idx = (src_y * src->width + src_x) * 4;
            int dst_idx = (y * target_w + x) * 4;

            dst->pixels[dst_idx + 0] = src->pixels[src_idx + 0];
            dst->pixels[dst_idx + 1] = src->pixels[src_idx + 1];
            dst->pixels[dst_idx + 2] = src->pixels[src_idx + 2];
            dst->pixels[dst_idx + 3] = src->pixels[src_idx + 3];
        }
    }

    return dst;
}

void generate_output(ChafaConfig* cfg, RGBAImage* img) {
    const char* chars_full = "@%#*+=-:. ";
    const char* chars_ascii = "Mo.  ";

    const char* chars = chars_full;
    if (cfg->colors && strcmp(cfg->colors, "none") == 0) {
        chars = chars_ascii;
    }

    // Scale image to output size
    RGBAImage* scaled = scale_image(img, cfg->width, cfg->height);

    if (!scaled || !scaled->pixels) {
        printf("%c\n", chars[0]);
        if (scaled) free_image(scaled);
        return;
    }

    // Convert each block to a character
    const char* char_palette = chars;
    int char_count = strlen(char_palette);

    for (int y = 0; y < scaled->height; y++) {
        for (int x = 0; x < scaled->width; x++) {
            int idx = (y * scaled->width + x) * 4;
            uint8_t r = scaled->pixels[idx + 0];
            uint8_t g = scaled->pixels[idx + 1];
            uint8_t b = scaled->pixels[idx + 2];

            int luminance = (r * 299 + g * 587 + b * 114) / 1000;
            int char_idx = (luminance * char_count) / 256;
            if (char_idx >= char_count) char_idx = char_count - 1;
            if (char_idx < 0) char_idx = 0;

            printf("%c", char_palette[char_idx]);
        }
        printf("\n");
    }

    free_image(scaled);
}

int main(int argc, char **argv) {
    ChafaConfig *cfg = config_new();
    int file_count = 0;
    char **files = malloc(sizeof(char*) * 256);

    // Parse arguments
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];

        if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0) {
            print_help(argv[0]);
            free(files);
            free(cfg);
            return 0;
        }

        if (strcmp(arg, "--version") == 0) {
            print_version();
            free(files);
            free(cfg);
            return 0;
        }

        if (strcmp(arg, "-v") == 0 || strcmp(arg, "--verbose") == 0) {
            cfg->verbose = 1;
            continue;
        }

        // Parse options with = syntax
        if (strchr(arg, '=')) {
            char* eq = strchr(arg, '=');
            char* value = eq + 1;

            if (strncmp(arg, "-f", 2) == 0 || strncmp(arg, "--format", 8) == 0) {
                cfg->format = value;
            } else if (strncmp(arg, "-s", 2) == 0 || strncmp(arg, "--size", 6) == 0) {
                cfg->size = value;
                sscanf(value, "%dx%d", &cfg->width, &cfg->height);
            } else if (strncmp(arg, "-c", 2) == 0 || strncmp(arg, "--colors", 8) == 0) {
                cfg->colors = value;
            } else if (strncmp(arg, "--bg", 4) == 0) {
                cfg->bg = value;
            } else if (strncmp(arg, "--fg", 4) == 0) {
                cfg->fg = value;
            }
            continue;
        }

        // Skip other options
        if (arg[0] == '-') {
            if (i + 1 < argc && argv[i+1][0] != '-') {
                i++;
            }
            continue;
        }

        // It's a file
        files[file_count++] = arg;
    }

    if (file_count == 0) {
        fprintf(stderr, "Usage:\n  %s [OPTION...] [FILE...]\n\n  Chafa (Character Art Facsimile) terminal graphics and character art generator.\n", argv[0]);
        free(files);
        free(cfg);
        return 1;
    }

    for (int i = 0; i < file_count; i++) {
        struct stat st;
        if (stat(files[i], &st) != 0) {
            fprintf(stderr, "%s: Failed to open '%s': No such file or directory\n", argv[0], files[i]);
            free(files);
            free(cfg);
            return 2;
        }

        RGBAImage *img = load_image(files[i]);
        if (!img) {
            fprintf(stderr, "%s: Failed to open '%s': No such file or directory\n", argv[0], files[i]);
            free(files);
            free(cfg);
            return 2;
        }

        generate_output(cfg, img);
        free_image(img);
    }

    free(files);
    free(cfg);
    return 0;
}
